# Mapa de colores: paleta de bezel (azul noche + lavanda) → Catppuccin Mocha.
# Lo lee recolor.pl. Formatos de línea:
#
#   hex  <desde> <hasta>      6 dígitos hexadecimales sin '#'. Se reemplazan dentro de
#                             #rrggbb, #aarrggbb, #rrggbbaa, rgb(rrggbb) y rgba(rrggbbaa),
#                             conservando el canal alfa.
#   text <desde> => <hasta>   texto literal, para los rgba() en decimal.
#
# Todo se reemplaza en una sola pasada: un destino nunca se vuelve a mapear.
# Un color que no esté aquí se queda como está (negros, blancos y grises neutros).

# ── Superficies (de más oscura a más clara) ──────────────────────────────────
hex 05080f 11111b   # fondo oscurecido detrás de los paneles
hex 0a0f1c 11111b   # crust: lo más oscuro
hex 0f0f14 181825
hex 0b1120 181825
hex 0d1424 181825
hex 0f1628 181825   # mantle: marco, barra y paneles
hex 151923 181825
hex 171b26 181825
hex 18223a 1e1e2e   # base: tarjetas dentro de los paneles
hex 1e2430 1e1e2e
hex 222218 1e1e2e
hex 202c48 313244   # surface0: hover y bordes inactivos
hex 283043 313244
hex 31363b 313244
hex 2a3756 45475a   # surface1: pistas, bordes y filas seleccionadas
hex 3a4560 45475a
hex 3f3a36 45475a
hex 34436a 585b70   # surface2
hex 4a5064 585b70
hex 4a5675 6c7086   # overlay0: texto atenuado
hex 29244d 3c344f   # contenedor tonal del acento (mauve al 20% sobre mantle)
hex 160f33 11111b   # texto sobre el acento

# ── Texto ────────────────────────────────────────────────────────────────────
